-- Ispravke formulacija, saveta i redosleda desne kolone za povezivanje u banci Prirode i društva (3. i 4. razred).
create schema if not exists private;

do $$
begin
  if to_regclass('private.questions_pid_backup_20261117') is null then
    execute $bak$
      create table private.questions_pid_backup_20261117 as
      select q.*
      from public.questions q
      join public.topics t on t.id = q.topic_id
      where t.subject = 'priroda_drustvo'
    $bak$;
  end if;
end $$;

do $$
declare
  v_owner uuid;
  v_broj int;
begin
  select count(*) into v_broj from public.admin_settings where is_platform_owner;
  if v_broj <> 1 then
    raise exception 'Ispravka zahteva tačno jednog vlasnika platforme; pronađeno: %', v_broj;
  end if;
  select user_id into strict v_owner from public.admin_settings where is_platform_owner;

  update public.questions q
  set
    text = u.text,
    options = u.options,
    explanation = u.explanation,
    hint = u.hint
  from jsonb_to_recordset('[{"gen_signature":"pid-priroda-covek-drustvo-3:banka:delatnosti-vocarstvo","text":"Koje je zanimanje posebno razvijeno u kraju sa mnogo zasada jabuka?","options":[{"id":"o0","text":"rudar"},{"id":"o1","text":"mornar"},{"id":"o2","text":"voćar"},{"id":"o3","text":"aviomehaničar"}],"explanation":"Voćar uzgaja voćke i brine o voćnjaku.","hint":"Jabuka pripada voću."},{"gen_signature":"pid-priroda-covek-drustvo-3:banka:vode-delovi-parovi","text":"Poveži opis mesta uz reku sa odgovarajućim nazivom.","options":{"left":[{"id":"l0","text":"Voda izlazi iz zemlje"},{"id":"l1","text":"Reka se završava ulivanjem"},{"id":"l2","text":"Udubljenje kojim voda teče"},{"id":"l3","text":"Kopno neposredno uz vodu"}],"right":[{"id":"r3","text":"obala"},{"id":"r2","text":"korito"},{"id":"r0","text":"izvor"},{"id":"r1","text":"ušće"}]},"explanation":"Tačni parovi: Voda izlazi iz zemlje — izvor; Reka se završava ulivanjem — ušće; Udubljenje kojim voda teče — korito; Kopno neposredno uz vodu — obala.","hint":"Razlikuj početak, kraj, udubljenje i kopno uz tok."},{"gen_signature":"pid-priroda-covek-drustvo-3:banka:delatnosti-grane-parovi","text":"Poveži rad u poljoprivredi sa granom kojoj pripada.","options":{"left":[{"id":"l0","text":"Gajenje kukuruza"},{"id":"l1","text":"Gajenje šljiva"},{"id":"l2","text":"Gajenje ovaca"},{"id":"l3","text":"Gajenje vinove loze"}],"right":[{"id":"r3","text":"vinogradarstvo"},{"id":"r2","text":"stočarstvo"},{"id":"r1","text":"voćarstvo"},{"id":"r0","text":"ratarstvo"}]},"explanation":"Tačni parovi: Gajenje kukuruza — ratarstvo; Gajenje šljiva — voćarstvo; Gajenje ovaca — stočarstvo; Gajenje vinove loze — vinogradarstvo.","hint":"Posmatraj šta se gaji."},{"gen_signature":"pid-priroda-covek-drustvo-3:banka:zajednice-prilagodjenost-parovi","text":"Poveži osobinu živog bića sa njenom ulogom.","options":{"left":[{"id":"l0","text":"Plovne kožice patke"},{"id":"l1","text":"Koren hrasta"},{"id":"l2","text":"Krila laste"},{"id":"l3","text":"Peraja ribe"}],"right":[{"id":"r0","text":"olakšavaju plivanje"},{"id":"r2","text":"omogućavaju let"},{"id":"r3","text":"pomažu kretanje u vodi"},{"id":"r1","text":"učvršćuje drvo u zemljištu"}]},"explanation":"Tačni parovi: Plovne kožice patke — olakšavaju plivanje; Koren hrasta — učvršćuje drvo u zemljištu; Krila laste — omogućavaju let; Peraja ribe — pomažu kretanje u vodi.","hint":"Poveži deo tela sa kretanjem ili opstankom."},{"gen_signature":"pid-priroda-covek-drustvo-3:banka:delatnosti-sirovine-parovi","text":"Poveži sirovinu sa proizvodom koji se od nje pravi.","options":{"left":[{"id":"l0","text":"Zrno pšenice"},{"id":"l1","text":"Ovčja vuna"},{"id":"l2","text":"Suncokretovo seme"},{"id":"l3","text":"Plod šljive"}],"right":[{"id":"r3","text":"pekmez od šljiva"},{"id":"r0","text":"pšenično brašno"},{"id":"r1","text":"vuneni šal"},{"id":"r2","text":"suncokretovo ulje"}]},"explanation":"Tačni parovi: Zrno pšenice — pšenično brašno; Ovčja vuna — vuneni šal; Suncokretovo seme — suncokretovo ulje; Plod šljive — pekmez od šljiva.","hint":"Prati poreklo proizvoda."},{"gen_signature":"pid-priroda-covek-drustvo-3:banka:naselja-ustanove-parovi","text":"Poveži potrebu stanovnika sa mestom gde se obično zadovoljava.","options":{"left":[{"id":"l0","text":"Pozajmljivanje knjige"},{"id":"l1","text":"Kupovina poštanske marke"},{"id":"l2","text":"Popravka obuće"},{"id":"l3","text":"Kupovina hleba"}],"right":[{"id":"r3","text":"pekara"},{"id":"r1","text":"pošta"},{"id":"r2","text":"obućarska radionica"},{"id":"r0","text":"biblioteka"}]},"explanation":"Tačni parovi: Pozajmljivanje knjige — biblioteka; Kupovina poštanske marke — pošta; Popravka obuće — obućarska radionica; Kupovina hleba — pekara.","hint":"Svako mesto pruža drugačiju uslugu ili proizvod."},{"gen_signature":"pid-orijentacija-3:banka:pravci-sporedni-parovi","text":"Poveži dve glavne strane sveta sa stranom između njih.","options":{"left":[{"id":"l0","text":"Sever i zapad"},{"id":"l1","text":"Jug i istok"},{"id":"l2","text":"Sever i istok"},{"id":"l3","text":"Jug i zapad"}],"right":[{"id":"r2","text":"severoistok"},{"id":"r0","text":"severozapad"},{"id":"r1","text":"jugoistok"},{"id":"r3","text":"jugozapad"}]},"explanation":"Tačni parovi: Sever i zapad — severozapad; Jug i istok — jugoistok; Sever i istok — severoistok; Jug i zapad — jugozapad.","hint":"Svaki naziv sastoji se od dve navedene strane."},{"gen_signature":"pid-orijentacija-3:banka:polozaj-povratak-parovi","text":"Poveži smer odlaska sa smerom povratka istim putem.","options":{"left":[{"id":"l0","text":"Odlazak na severoistok"},{"id":"l1","text":"Odlazak na severozapad"},{"id":"l2","text":"Odlazak na jugoistok"},{"id":"l3","text":"Odlazak na jugozapad"}],"right":[{"id":"r0","text":"povratak na jugozapad"},{"id":"r3","text":"povratak na severoistok"},{"id":"r1","text":"povratak na jugoistok"},{"id":"r2","text":"povratak na severozapad"}]},"explanation":"Tačni parovi: Odlazak na severoistok — povratak na jugozapad; Odlazak na severozapad — povratak na jugoistok; Odlazak na jugoistok — povratak na severozapad; Odlazak na jugozapad — povratak na severoistok.","hint":"Pri povratku oba dela smera postaju suprotna."},{"gen_signature":"pid-orijentacija-3:banka:kalendar-kvartali-parovi","text":"Poveži grupu meseci sa njenim mestom u godini.","options":{"left":[{"id":"l0","text":"Januar, februar, mart"},{"id":"l1","text":"April, maj, jun"},{"id":"l2","text":"Jul, avgust, septembar"},{"id":"l3","text":"Oktobar, novembar, decembar"}],"right":[{"id":"r1","text":"četvrti do šestog meseca"},{"id":"r0","text":"prva tri meseca"},{"id":"r2","text":"sedmi do devetog meseca"},{"id":"r3","text":"poslednja tri meseca"}]},"explanation":"Tačni parovi: Januar, februar, mart — prva tri meseca; April, maj, jun — četvrti do šestog meseca; Jul, avgust, septembar — sedmi do devetog meseca; Oktobar, novembar, decembar — poslednja tri meseca.","hint":"Poređaj mesece od januara do decembra."},{"gen_signature":"pid-orijentacija-3:banka:vreme-trajanja-parovi","text":"Poveži trajanje aktivnosti sa intervalom istog dana.","options":{"left":[{"id":"l0","text":"Od 8 do 9"},{"id":"l1","text":"Od 9 do 11"},{"id":"l2","text":"Od 12 do 15"},{"id":"l3","text":"Od 14 do 18"}],"right":[{"id":"r2","text":"3 časa"},{"id":"r0","text":"1 čas"},{"id":"r1","text":"2 časa"},{"id":"r3","text":"4 časa"}]},"explanation":"Tačni parovi: Od 8 do 9 — 1 čas; Od 9 do 11 — 2 časa; Od 12 do 15 — 3 časa; Od 14 do 18 — 4 časa.","hint":"Oduzmi početni čas od završnog."},{"gen_signature":"pid-orijentacija-3:banka:plan-znaci-parovi","text":"Legenda zamišljenog plana glasi: krug je igralište, kvadrat škola, trougao kamp, zvezda vidikovac. Poveži znakove sa mestima.","options":{"left":[{"id":"l0","text":"Krug"},{"id":"l1","text":"Kvadrat"},{"id":"l2","text":"Trougao"},{"id":"l3","text":"Zvezda"}],"right":[{"id":"r0","text":"igralište"},{"id":"r2","text":"kamp"},{"id":"r3","text":"vidikovac"},{"id":"r1","text":"škola"}]},"explanation":"Tačni parovi: Krug — igralište; Kvadrat — škola; Trougao — kamp; Zvezda — vidikovac.","hint":"Sva značenja su navedena u tekstu; nije potrebna slika."},{"gen_signature":"pid-proslost-3:banka:cuvanje-arhiv","text":"U kojoj ustanovi se organizovano čuvaju stare povelje, pisma i druga dokumenta?","options":[{"id":"o0","text":"u arhivu"},{"id":"o1","text":"u pekari"},{"id":"o2","text":"u garaži"},{"id":"o3","text":"u sportskoj hali"}],"explanation":"Arhivi prikupljaju, sređuju i čuvaju dokumenta važna za proučavanje prošlosti.","hint":"Potraži ustanovu specijalizovanu za čuvanje starih dokumenata."},{"gen_signature":"pid-proslost-3:banka:cuvanje-original-kopija","text":"U izložbi je izložena kopija starog pisma. Šta znači reč kopija?","options":[{"id":"o0","text":"naknadno napravljena reprodukcija originala"},{"id":"o1","text":"jedini izvorni primerak"},{"id":"o2","text":"pismo koje će tek biti napisano"},{"id":"o3","text":"predmet bez ikakve veze sa originalom"}],"explanation":"Kopija prikazuje original, ali nije isti izvorni predmet.","hint":"Razlikuj izvorni predmet i primerak nastao po uzoru na njega."},{"gen_signature":"pid-proslost-3:banka:cuvanje-strucnjaci-parovi","text":"Poveži stručnjaka sa poslom u istraživanju i čuvanju prošlosti.","options":{"left":[{"id":"l0","text":"Arheolog"},{"id":"l1","text":"Arhivista"},{"id":"l2","text":"Restaurator"},{"id":"l3","text":"Kustos"}],"right":[{"id":"r1","text":"sređuje i čuva arhivska dokumenta"},{"id":"r3","text":"proučava muzejsku zbirku i priprema izložbu"},{"id":"r2","text":"stručno obnavlja oštećene predmete"},{"id":"r0","text":"istražuje ostatke starih naselja"}]},"explanation":"Tačni parovi: Arheolog — istražuje ostatke starih naselja; Arhivista — sređuje i čuva arhivska dokumenta; Restaurator — stručno obnavlja oštećene predmete; Kustos — proučava muzejsku zbirku i priprema izložbu.","hint":"Pronađi ključnu reč koja opisuje posao."},{"gen_signature":"pid-proslost-3:banka:svakodnevica-alati-parovi","text":"Poveži stari alat ili uređaj sa njegovom namenom.","options":{"left":[{"id":"l0","text":"Srp"},{"id":"l1","text":"Preslica"},{"id":"l2","text":"Razboj"},{"id":"l3","text":"Žrvanj"}],"right":[{"id":"r0","text":"ručno žnjenje žita"},{"id":"r1","text":"priprema vlakana pri predenju"},{"id":"r3","text":"ručno mlevenje zrna"},{"id":"r2","text":"tkanje platna"}]},"explanation":"Tačni parovi: Srp — ručno žnjenje žita; Preslica — priprema vlakana pri predenju; Razboj — tkanje platna; Žrvanj — ručno mlevenje zrna.","hint":"Poveži svaki predmet sa drugačijim korakom rada."},{"gen_signature":"pid-proslost-3:banka:izvor-zapisi-parovi","text":"Poveži podatak iz zamišljenog zapisa sa onim što iz njega saznajemo.","options":{"left":[{"id":"l0","text":"„Kupljeno: 2 sveske”"},{"id":"l1","text":"„Putovali smo brodom”"},{"id":"l2","text":"„Škola otvorena 1954.”"},{"id":"l3","text":"„Pismo šalje Jelena”"}],"right":[{"id":"r0","text":"broj kupljenih svesaka"},{"id":"r1","text":"upotrebljeno prevozno sredstvo"},{"id":"r3","text":"ime pošiljaoca pisma"},{"id":"r2","text":"godina otvaranja škole"}]},"explanation":"Tačni parovi: „Kupljeno: 2 sveske” — broj kupljenih svesaka; „Putovali smo brodom” — upotrebljeno prevozno sredstvo; „Škola otvorena 1954.” — godina otvaranja škole; „Pismo šalje Jelena” — ime pošiljaoca pisma.","hint":"Koristi samo podatak koji je naveden."},{"gen_signature":"pid-proslost-3:banka:svakodnevica-zanati-parovi","text":"Poveži stari zanat sa proizvodom.","options":{"left":[{"id":"l0","text":"Grnčar"},{"id":"l1","text":"Kovač"},{"id":"l2","text":"Opančar"},{"id":"l3","text":"Bačvar"}],"right":[{"id":"r3","text":"drveno bure"},{"id":"r0","text":"glineni ćup"},{"id":"r1","text":"gvozdena potkovica"},{"id":"r2","text":"kožni opanak"}]},"explanation":"Tačni parovi: Grnčar — glineni ćup; Kovač — gvozdena potkovica; Opančar — kožni opanak; Bačvar — drveno bure.","hint":"Razmisli o materijalu i nameni proizvoda."},{"gen_signature":"pid-proslost-3:banka:cuvanje-postupci-parovi","text":"Poveži postupak sa njegovom svrhom u čuvanju prošlosti.","options":{"left":[{"id":"l0","text":"Skeniranje dokumenta"},{"id":"l1","text":"Označavanje predmeta brojem"},{"id":"l2","text":"Čuvanje pisma od vlage"},{"id":"l3","text":"Snimanje kazivanja uz dozvolu"}],"right":[{"id":"r1","text":"povezivanje sa zapisom u zbirci"},{"id":"r3","text":"čuvanje glasa i sećanja sagovornika"},{"id":"r0","text":"pravljenje digitalne kopije"},{"id":"r2","text":"zaštita papira od propadanja"}]},"explanation":"Tačni parovi: Skeniranje dokumenta — pravljenje digitalne kopije; Označavanje predmeta brojem — povezivanje sa zapisom u zbirci; Čuvanje pisma od vlage — zaštita papira od propadanja; Snimanje kazivanja uz dozvolu — čuvanje glasa i sećanja sagovornika.","hint":"Svaki postupak štiti drugačiji trag ili podatak."},{"gen_signature":"pid-kretanje-3:banka:kretanje-promene-parovi","text":"Poveži delovanje sa opisanom promenom kretanja.","options":{"left":[{"id":"l0","text":"Kočenje bicikla"},{"id":"l1","text":"Odbijanje lopte u stranu"},{"id":"l2","text":"Pokretanje mirnih kolica"},{"id":"l3","text":"Hvatanje lopte rukama"}],"right":[{"id":"r3","text":"zaustavljanje lopte"},{"id":"r2","text":"početak kretanja"},{"id":"r1","text":"promena pravca"},{"id":"r0","text":"smanjenje brzine"}]},"explanation":"Tačni parovi: Kočenje bicikla — smanjenje brzine; Odbijanje lopte u stranu — promena pravca; Pokretanje mirnih kolica — početak kretanja; Hvatanje lopte rukama — zaustavljanje lopte.","hint":"Prati stanje pre i posle delovanja."},{"gen_signature":"pid-kretanje-3:banka:ogled-uloge-parovi","text":"U ogledu autić puštamo niz istu rampu na različite podloge. Poveži podatak sa ulogom.","options":{"left":[{"id":"l0","text":"Vrsta podloge"},{"id":"l1","text":"Isti autić"},{"id":"l2","text":"Pređeni put"},{"id":"l3","text":"Tabela rezultata"}],"right":[{"id":"r1","text":"predmet koji zadržavamo"},{"id":"r2","text":"veličina koju merimo"},{"id":"r0","text":"uslov koji menjamo"},{"id":"r3","text":"mesto gde beležimo merenja"}]},"explanation":"Tačni parovi: Vrsta podloge — uslov koji menjamo; Isti autić — predmet koji zadržavamo; Pređeni put — veličina koju merimo; Tabela rezultata — mesto gde beležimo merenja.","hint":"Razdvoji promenu, stalni uslov, merenje i zapis."},{"gen_signature":"pid-kretanje-3:banka:svetlost-ponasanje-parovi","text":"Poveži predmet sa njegovim odnosom prema svetlosti.","options":{"left":[{"id":"l0","text":"Ogledalo"},{"id":"l1","text":"Čisto prozorsko staklo"},{"id":"l2","text":"Drvena vrata"},{"id":"l3","text":"Svetloodbojna traka"}],"right":[{"id":"r3","text":"vraća svetlost prema izvoru"},{"id":"r1","text":"omogućava jasan pogled kroz njega"},{"id":"r0","text":"pravilno odbija svetlost i daje lik"},{"id":"r2","text":"ne propuštaju svetlost kroz punu površinu"}]},"explanation":"Tačni parovi: Ogledalo — pravilno odbija svetlost i daje lik; Čisto prozorsko staklo — omogućava jasan pogled kroz njega; Drvena vrata — ne propuštaju svetlost kroz punu površinu; Svetloodbojna traka — vraća svetlost prema izvoru.","hint":"Uporedi odbijanje, propuštanje i zaklanjanje."},{"gen_signature":"pid-kretanje-3:banka:zvuk-opisi-parovi","text":"Poveži pojavu sa opisom zvuka.","options":{"left":[{"id":"l0","text":"Odjek"},{"id":"l1","text":"Visok ton"},{"id":"l2","text":"Dubok ton"},{"id":"l3","text":"Tišina posle zaustavljanja gumice"}],"right":[{"id":"r0","text":"zvuk koji se vratio posle odbijanja"},{"id":"r2","text":"ton nalik dubokom brujanju"},{"id":"r3","text":"prestanak treperenja izvora"},{"id":"r1","text":"ton nalik tankom zviždanju"}]},"explanation":"Tačni parovi: Odjek — zvuk koji se vratio posle odbijanja; Visok ton — ton nalik tankom zviždanju; Dubok ton — ton nalik dubokom brujanju; Tišina posle zaustavljanja gumice — prestanak treperenja izvora.","hint":"Visina tona nije isto što i jačina."},{"gen_signature":"pid-kretanje-3:banka:podloga-primene-parovi","text":"Poveži primer sa njegovom ulogom u kretanju.","options":{"left":[{"id":"l0","text":"Šara na đonu"},{"id":"l1","text":"Točkići na koferu"},{"id":"l2","text":"Kočnica na trotinetu"},{"id":"l3","text":"Rampa na ulazu"}],"right":[{"id":"r0","text":"pomaže prianjanje uz podlogu"},{"id":"r3","text":"omogućava prelazak visinske razlike"},{"id":"r1","text":"olakšavaju pomeranje kotrljanjem"},{"id":"r2","text":"pomaže zaustavljanje"}]},"explanation":"Tačni parovi: Šara na đonu — pomaže prianjanje uz podlogu; Točkići na koferu — olakšavaju pomeranje kotrljanjem; Kočnica na trotinetu — pomaže zaustavljanje; Rampa na ulazu — omogućava prelazak visinske razlike.","hint":"Pronađi praktičnu svrhu svakog predmeta."},{"gen_signature":"pid-materijali-3:banka:izbor-svojstva-parovi","text":"Poveži svojstvo sa primerom njegove primene.","options":{"left":[{"id":"l0","text":"Upijanje"},{"id":"l1","text":"Elastičnost"},{"id":"l2","text":"Providnost"},{"id":"l3","text":"Čvrstina"}],"right":[{"id":"r2","text":"stakleno okno kroz koje gledamo"},{"id":"r1","text":"gumena traka koja se rastegne pa vrati"},{"id":"r0","text":"pamučna krpa za brisanje vode"},{"id":"r3","text":"nogar stolice koji nosi teret"}]},"explanation":"Tačni parovi: Upijanje — pamučna krpa za brisanje vode; Elastičnost — gumena traka koja se rastegne pa vrati; Providnost — stakleno okno kroz koje gledamo; Čvrstina — nogar stolice koji nosi teret.","hint":"Svaki predmet koristi drugačije svojstvo."},{"gen_signature":"pid-materijali-3:banka:tecnosti-merenje-parovi","text":"Poveži opis sa pojmom u posmatranju tečnosti.","options":{"left":[{"id":"l0","text":"Koliko prostora voda zauzima"},{"id":"l1","text":"Prelazak vode preko ivice posude"},{"id":"l2","text":"Prebacivanje vode u drugu posudu"},{"id":"l3","text":"Voda ulazi u pore krpe"}],"right":[{"id":"r2","text":"presipanje"},{"id":"r3","text":"upijanje"},{"id":"r0","text":"zapremina"},{"id":"r1","text":"prosipanje"}]},"explanation":"Tačni parovi: Koliko prostora voda zauzima — zapremina; Prelazak vode preko ivice posude — prosipanje; Prebacivanje vode u drugu posudu — presipanje; Voda ulazi u pore krpe — upijanje.","hint":"Razlikuj količinu i postupke sa vodom."},{"gen_signature":"pid-materijali-3:banka:izbor-namena-parovi","text":"Poveži predmet sa potrebnim svojstvom materijala.","options":{"left":[{"id":"l0","text":"Kuhinjski peškir"},{"id":"l1","text":"Kišni mantil"},{"id":"l2","text":"Sočivo lupe"},{"id":"l3","text":"Zaštitna sunđerasta obloga"}],"right":[{"id":"r2","text":"propušta svetlost"},{"id":"r0","text":"dobro upija vodu"},{"id":"r3","text":"ublažava udarce"},{"id":"r1","text":"ne propušta vodu"}]},"explanation":"Tačni parovi: Kuhinjski peškir — dobro upija vodu; Kišni mantil — ne propušta vodu; Sočivo lupe — propušta svetlost; Zaštitna sunđerasta obloga — ublažava udarce.","hint":"Pođi od namene predmeta."},{"gen_signature":"pid-materijali-3:banka:ogled-koraci-parovi","text":"Poveži korak istraživanja sa njegovim primerom.","options":{"left":[{"id":"l0","text":"Pitanje"},{"id":"l1","text":"Pretpostavka"},{"id":"l2","text":"Merenje"},{"id":"l3","text":"Zaključak"}],"right":[{"id":"r2","text":"Brojimo upijene kašičice vode."},{"id":"r0","text":"Koji papir više upija?"},{"id":"r1","text":"Mislim da deblji papir upija više."},{"id":"r3","text":"U našem ogledu deblji papir upio je više."}]},"explanation":"Tačni parovi: Pitanje — Koji papir više upija?; Pretpostavka — Mislim da deblji papir upija više.; Merenje — Brojimo upijene kašičice vode.; Zaključak — U našem ogledu deblji papir upio je više..","hint":"Razlikuj ono što pitamo, očekujemo, merimo i zaključujemo."},{"gen_signature":"pid-materijali-3:banka:promene-opazanja-parovi","text":"Poveži opaženu promenu sa opisom.","options":{"left":[{"id":"l0","text":"Sečenje kartona"},{"id":"l1","text":"Rastezanje gumene trake"},{"id":"l2","text":"Brisanje bare sunđerom"},{"id":"l3","text":"Sušenje mokre tkanine"}],"right":[{"id":"r3","text":"voda odlazi u vazduh kao para"},{"id":"r0","text":"nastaju manji komadi istog materijala"},{"id":"r1","text":"povećava se njena dužina"},{"id":"r2","text":"voda prelazi u pore sunđera"}]},"explanation":"Tačni parovi: Sečenje kartona — nastaju manji komadi istog materijala; Rastezanje gumene trake — povećava se njena dužina; Brisanje bare sunđerom — voda prelazi u pore sunđera; Sušenje mokre tkanine — voda odlazi u vazduh kao para.","hint":"Prati šta se menja u svakom primeru."},{"gen_signature":"pid-beograd-3:banka:kultura-muzeji-parovi","text":"Poveži beogradsku ustanovu sa temom posete.","options":{"left":[{"id":"l0","text":"Muzej Nikole Tesle"},{"id":"l1","text":"Etnografski muzej"},{"id":"l2","text":"Muzej vazduhoplovstva"},{"id":"l3","text":"Botanička bašta Jevremovac"}],"right":[{"id":"r2","text":"istorija letenja"},{"id":"r1","text":"narodne nošnje i običaji"},{"id":"r3","text":"raznovrsnost biljaka"},{"id":"r0","text":"Teslini izumi i zaostavština"}]},"explanation":"Tačni parovi: Muzej Nikole Tesle — Teslini izumi i zaostavština; Etnografski muzej — narodne nošnje i običaji; Muzej vazduhoplovstva — istorija letenja; Botanička bašta Jevremovac — raznovrsnost biljaka.","hint":"Tema se često prepoznaje u nazivu ustanove."},{"gen_signature":"pid-beograd-3:banka:grad-naselja-parovi","text":"Poveži beogradsko mesto sa opisom koji mu odgovara.","options":{"left":[{"id":"l0","text":"Gardoš"},{"id":"l1","text":"Vinča – Belo brdo"},{"id":"l2","text":"Topčider"},{"id":"l3","text":"Kalenić pijaca"}],"right":[{"id":"r1","text":"arheološko naselje uz Dunav"},{"id":"r0","text":"brdo sa kulom u Zemunu"},{"id":"r2","text":"prostor sa Konakom kneza Miloša"},{"id":"r3","text":"mesto kupovine na tezgama"}]},"explanation":"Tačni parovi: Gardoš — brdo sa kulom u Zemunu; Vinča – Belo brdo — arheološko naselje uz Dunav; Topčider — prostor sa Konakom kneza Miloša; Kalenić pijaca — mesto kupovine na tezgama.","hint":"Razlikuj brdo, lokalitet, istorijski prostor i pijacu."},{"gen_signature":"pid-beograd-3:banka:poseta-priprema-parovi","text":"Odeljenje planira posetu ustanovama u Beogradu. Poveži pripremu sa svrhom.","options":{"left":[{"id":"l0","text":"Provera radnog vremena"},{"id":"l1","text":"Dogovor mesta okupljanja"},{"id":"l2","text":"Čitanje pravila posete"},{"id":"l3","text":"Provera pristupa rampom"}],"right":[{"id":"r2","text":"poštovanje uslova ustanove"},{"id":"r3","text":"planiranje pristupa za kolica"},{"id":"r1","text":"lakše nalaženje grupe"},{"id":"r0","text":"dolazak dok je ustanova otvorena"}]},"explanation":"Tačni parovi: Provera radnog vremena — dolazak dok je ustanova otvorena; Dogovor mesta okupljanja — lakše nalaženje grupe; Čitanje pravila posete — poštovanje uslova ustanove; Provera pristupa rampom — planiranje pristupa za kolica.","hint":"Svaka priprema rešava drugačiju potrebu posete."},{"gen_signature":"pid-beograd-3:banka:vinca-istrazivanje-parovi","text":"Poveži trag iz zamišljenog istraživanja naselja u Vinči kod Beograda sa mogućim podatkom.","options":{"left":[{"id":"l0","text":"Ostaci zidova kuće"},{"id":"l1","text":"Posuda sa ukrasom"},{"id":"l2","text":"Ostaci zrnevlja"},{"id":"l3","text":"Kamena alatka sa tragovima rada"}],"right":[{"id":"r0","text":"način gradnje"},{"id":"r3","text":"upotreba oruđa"},{"id":"r1","text":"oblikovanje i ukrašavanje posuđa"},{"id":"r2","text":"biljke koje su korišćene"}]},"explanation":"Tačni parovi: Ostaci zidova kuće — način gradnje; Posuda sa ukrasom — oblikovanje i ukrašavanje posuđa; Ostaci zrnevlja — biljke koje su korišćene; Kamena alatka sa tragovima rada — upotreba oruđa.","hint":"Zaključuj o nameni i materijalu sačuvanog traga."},{"gen_signature":"pid-beograd-3:banka:basta-delovi-parovi","text":"Poveži deo uređene botaničke zbirke u Beogradu sa njegovom namenom.","options":{"left":[{"id":"l0","text":"Tabla sa nazivom biljke"},{"id":"l1","text":"Staklenik"},{"id":"l2","text":"Uređena staza"},{"id":"l3","text":"Herbarijumski primerak"}],"right":[{"id":"r1","text":"održavanje posebnih uslova toplote"},{"id":"r2","text":"kretanje posetilaca bez gaženja zasada"},{"id":"r3","text":"sačuvana osušena biljka za proučavanje"},{"id":"r0","text":"prepoznavanje vrste"}]},"explanation":"Tačni parovi: Tabla sa nazivom biljke — prepoznavanje vrste; Staklenik — održavanje posebnih uslova toplote; Uređena staza — kretanje posetilaca bez gaženja zasada; Herbarijumski primerak — sačuvana osušena biljka za proučavanje.","hint":"Posmatraj zbirku kao mesto učenja i čuvanja biljaka."},{"gen_signature":"pid-odlike-srbije-4:banka:reke-morava","text":"Spajanjem kojih reka nastaje Velika Morava?","options":[{"id":"o0","text":"Južne i Zapadne Morave"},{"id":"o1","text":"Save i Drine"},{"id":"o2","text":"Tise i Dunava"},{"id":"o3","text":"Ibra i Lima"}],"explanation":"Velika Morava nastaje spajanjem Južne i Zapadne Morave.","hint":"Spoji dva kraka reke istog imena."},{"gen_signature":"pid-odlike-srbije-4:banka:banje-voda","text":"Koji prirodni resurs je posebno značajan za razvoj mnogih banja u Srbiji?","options":[{"id":"o0","text":"izvori mineralne i termalne vode"},{"id":"o1","text":"isključivo morska obala"},{"id":"o2","text":"polarni led"},{"id":"o3","text":"pustinjske peščane dine"}],"explanation":"Mnoge banje razvile su se uz izvore mineralnih i toplih voda.","hint":"Razmisli po čemu su banje poznate i lekovite."},{"gen_signature":"pid-odlike-srbije-4:banka:reke-gradovi-parovi","text":"Poveži grad sa rekom koja kroz njega protiče.","options":{"left":[{"id":"l0","text":"Niš"},{"id":"l1","text":"Kraljevo"},{"id":"l2","text":"Čačak"},{"id":"l3","text":"Valjevo"}],"right":[{"id":"r0","text":"Nišava"},{"id":"r1","text":"Ibar"},{"id":"r3","text":"Kolubara"},{"id":"r2","text":"Zapadna Morava"}]},"explanation":"Tačni parovi: Niš — Nišava; Kraljevo — Ibar; Čačak — Zapadna Morava; Valjevo — Kolubara.","hint":"Poveži geografsko ime sa gradom njegovog toka."},{"gen_signature":"pid-odlike-srbije-4:banka:predeli-primeri-parovi","text":"Poveži prirodnu znamenitost Srbije sa vrstom predela.","options":{"left":[{"id":"l0","text":"Đerdap"},{"id":"l1","text":"Resavska pećina"},{"id":"l2","text":"Đavolja varoš"},{"id":"l3","text":"Deliblatska peščara"}],"right":[{"id":"r3","text":"prostor peščanog zemljišta"},{"id":"r1","text":"podzemna šupljina sa pećinskim nakitom"},{"id":"r2","text":"zemljane figure"},{"id":"r0","text":"klisura Dunava"}]},"explanation":"Tačni parovi: Đerdap — klisura Dunava; Resavska pećina — podzemna šupljina sa pećinskim nakitom; Đavolja varoš — zemljane figure; Deliblatska peščara — prostor peščanog zemljišta.","hint":"Traži glavnu osobinu svakog mesta."},{"gen_signature":"pid-odlike-srbije-4:banka:privreda-veze-parovi","text":"Poveži sirovinu sa delatnošću koja je prerađuje.","options":{"left":[{"id":"l0","text":"Pšenica"},{"id":"l1","text":"Mleko"},{"id":"l2","text":"Drvo"},{"id":"l3","text":"Voće"}],"right":[{"id":"r2","text":"radionica nameštaja"},{"id":"r0","text":"mlin koji pravi brašno"},{"id":"r1","text":"mlekara koja pravi sir"},{"id":"r3","text":"pogon za sokove"}]},"explanation":"Tačni parovi: Pšenica — mlin koji pravi brašno; Mleko — mlekara koja pravi sir; Drvo — radionica nameštaja; Voće — pogon za sokove.","hint":"Zamisli proizvod koji može da nastane."},{"gen_signature":"pid-odlike-srbije-4:banka:nasledje-vrste-parovi","text":"Poveži primer nasleđa sa opisom.","options":{"left":[{"id":"l0","text":"Stari manastir"},{"id":"l1","text":"Narodna pesma"},{"id":"l2","text":"Ćilim izrađen tradicionalnom tehnikom"},{"id":"l3","text":"Kolo"}],"right":[{"id":"r2","text":"predmet zanatskog umeća"},{"id":"r1","text":"usmeno i muzičko stvaralaštvo"},{"id":"r3","text":"zajednička tradicionalna igra"},{"id":"r0","text":"istorijska građevina"}]},"explanation":"Tačni parovi: Stari manastir — istorijska građevina; Narodna pesma — usmeno i muzičko stvaralaštvo; Ćilim izrađen tradicionalnom tehnikom — predmet zanatskog umeća; Kolo — zajednička tradicionalna igra.","hint":"Razlikuj građevinu, pesmu, predmet i izvođenje."},{"gen_signature":"pid-odlike-srbije-4:banka:resursi-koriscenje-parovi","text":"Poveži resurs Srbije sa odgovornim korišćenjem.","options":{"left":[{"id":"l0","text":"Plodno zemljište"},{"id":"l1","text":"Mineralni izvor"},{"id":"l2","text":"Pećinski nakit"},{"id":"l3","text":"Planinske staze"}],"right":[{"id":"r2","text":"posmatranje bez lomljenja"},{"id":"r1","text":"čuvanje izvorišta od zagađenja"},{"id":"r3","text":"kretanje označenim putem"},{"id":"r0","text":"sprečavanje nepotrebnog zagađenja njiva"}]},"explanation":"Tačni parovi: Plodno zemljište — sprečavanje nepotrebnog zagađenja njiva; Mineralni izvor — čuvanje izvorišta od zagađenja; Pećinski nakit — posmatranje bez lomljenja; Planinske staze — kretanje označenim putem.","hint":"Razmisli kako se vrednost čuva i tokom korišćenja."},{"gen_signature":"pid-covek-4:banka:emocije-primeri-parovi","text":"Poveži opis doživljaja sa osećanjem koje dete imenuje.","options":{"left":[{"id":"l0","text":"„Žao mi je zbog rastanka”"},{"id":"l1","text":"„Radujem se susretu”"},{"id":"l2","text":"„Brinem pred nepoznatim zadatkom”"},{"id":"l3","text":"„Ljut sam zbog nepravde”"}],"right":[{"id":"r1","text":"radost"},{"id":"r3","text":"ljutnja"},{"id":"r2","text":"zabrinutost"},{"id":"r0","text":"tuga"}]},"explanation":"Tačni parovi: „Žao mi je zbog rastanka” — tuga; „Radujem se susretu” — radost; „Brinem pred nepoznatim zadatkom” — zabrinutost; „Ljut sam zbog nepravde” — ljutnja.","hint":"Slušaj reči kojima dete opisuje doživljaj."},{"gen_signature":"pid-covek-4:banka:granice-postupci-parovi","text":"Poveži situaciju sa odgovornim postupkom.","options":{"left":[{"id":"l0","text":"Ne želiš dodir"},{"id":"l1","text":"Drugi kaže da mu nešto ne prija"},{"id":"l2","text":"Traže opasnu tajnu"},{"id":"l3","text":"Fotografija druga treba da se objavi"}],"right":[{"id":"r1","text":"prestaneš sa tim postupkom"},{"id":"r0","text":"jasno kažeš da ne želiš"},{"id":"r2","text":"obratiš se odraslom od poverenja"},{"id":"r3","text":"najpre pitaš za dozvolu"}]},"explanation":"Tačni parovi: Ne želiš dodir — jasno kažeš da ne želiš; Drugi kaže da mu nešto ne prija — prestaneš sa tim postupkom; Traže opasnu tajnu — obratiš se odraslom od poverenja; Fotografija druga treba da se objavi — najpre pitaš za dozvolu.","hint":"Poštuj i svoje i tuđe granice."},{"gen_signature":"pid-covek-4:banka:saradnja-vestine-parovi","text":"Poveži veštinu saradnje sa primerom.","options":{"left":[{"id":"l0","text":"Slušanje"},{"id":"l1","text":"Dogovaranje"},{"id":"l2","text":"Podrška"},{"id":"l3","text":"Odgovornost"}],"right":[{"id":"r2","text":"ohrabriš druga posle greške"},{"id":"r0","text":"sačekaš da drugi završi rečenicu"},{"id":"r1","text":"zajedno podelite uloge"},{"id":"r3","text":"uradiš svoj dogovoreni deo"}]},"explanation":"Tačni parovi: Slušanje — sačekaš da drugi završi rečenicu; Dogovaranje — zajedno podelite uloge; Podrška — ohrabriš druga posle greške; Odgovornost — uradiš svoj dogovoreni deo.","hint":"Razmisli kako postupak doprinosi grupi."},{"gen_signature":"pid-covek-4:banka:higijena-predmeti-parovi","text":"Poveži predmet lične higijene sa namenom.","options":{"left":[{"id":"l0","text":"Četkica za zube"},{"id":"l1","text":"Češalj"},{"id":"l2","text":"Čist peškir"},{"id":"l3","text":"Papirna maramica"}],"right":[{"id":"r1","text":"uređivanje kose"},{"id":"r0","text":"čišćenje zuba"},{"id":"r3","text":"brisanje nosa"},{"id":"r2","text":"sušenje oprane kože"}]},"explanation":"Tačni parovi: Četkica za zube — čišćenje zuba; Češalj — uređivanje kose; Čist peškir — sušenje oprane kože; Papirna maramica — brisanje nosa.","hint":"Razlikuj namene predmeta; lične predmete koristimo higijenski."},{"gen_signature":"pid-covek-4:banka:podrska-situacije-parovi","text":"Poveži potrebu sa primerom traženja podrške.","options":{"left":[{"id":"l0","text":"Ne razumem zadatak"},{"id":"l1","text":"Imam pitanje o promenama tela"},{"id":"l2","text":"Neko me uporno ponižava"},{"id":"l3","text":"Ulaz ima samo stepenice, a koristim kolica"}],"right":[{"id":"r0","text":"pitam nastavnika da objasni korak"},{"id":"r3","text":"tražim pristupačan ulaz"},{"id":"r2","text":"tražim pomoć u zaustavljanju nasilja"},{"id":"r1","text":"razgovaram sa pouzdanim odraslim ili zdravstvenim radnikom"}]},"explanation":"Tačni parovi: Ne razumem zadatak — pitam nastavnika da objasni korak; Imam pitanje o promenama tela — razgovaram sa pouzdanim odraslim ili zdravstvenim radnikom; Neko me uporno ponižava — tražim pomoć u zaustavljanju nasilja; Ulaz ima samo stepenice, a koristim kolica — tražim pristupačan ulaz.","hint":"Različite potrebe zaslužuju odgovarajuću pomoć."},{"gen_signature":"pid-materijali-4:banka:struja-delovi-parovi","text":"Poveži deo jednostavnog baterijskog kola sa njegovom ulogom.","options":{"left":[{"id":"l0","text":"Baterija"},{"id":"l1","text":"Žica"},{"id":"l2","text":"Sijalica"},{"id":"l3","text":"Prekidač"}],"right":[{"id":"r0","text":"izvor električne energije"},{"id":"r2","text":"pretvara deo energije u svetlost"},{"id":"r3","text":"otvara ili zatvara strujno kolo"},{"id":"r1","text":"provodna veza delova"}]},"explanation":"Tačni parovi: Baterija — izvor električne energije; Žica — provodna veza delova; Sijalica — pretvara deo energije u svetlost; Prekidač — otvara ili zatvara strujno kolo.","hint":"Prati ulogu svakog dela u celini."},{"gen_signature":"pid-materijali-4:banka:smese-izbor-parovi","text":"Poveži smešu sa prikladnim postupkom izdvajanja navedenog sastojka.","options":{"left":[{"id":"l0","text":"Gvožđe iz peska"},{"id":"l1","text":"Kamenčići iz pasulja"},{"id":"l2","text":"Krupni šljunak iz sitnog peska"},{"id":"l3","text":"So iz slane vode"}],"right":[{"id":"r1","text":"ručno izdvajanje"},{"id":"r0","text":"privlačenje magnetom"},{"id":"r3","text":"isparavanje vode"},{"id":"r2","text":"prosejavanje kroz odgovarajuće sito"}]},"explanation":"Tačni parovi: Gvožđe iz peska — privlačenje magnetom; Kamenčići iz pasulja — ručno izdvajanje; Krupni šljunak iz sitnog peska — prosejavanje kroz odgovarajuće sito; So iz slane vode — isparavanje vode.","hint":"Iskoristi različita svojstva sastojaka."},{"gen_signature":"pid-materijali-4:banka:magnet-primene-parovi","text":"Poveži opažanje sa zaključkom o magnetu.","options":{"left":[{"id":"l0","text":"Spajalica se pomera bez dodira"},{"id":"l1","text":"Gvožđe se izdvaja iz peska"},{"id":"l2","text":"Aluminijum ostaje neprivučen"},{"id":"l3","text":"Udaljenija spajalica se ne pomera"}],"right":[{"id":"r3","text":"rastojanje utiče na delovanje"},{"id":"r2","text":"nisu svi metali privučeni"},{"id":"r0","text":"delovanje je moguće na daljinu"},{"id":"r1","text":"magnet pomaže razdvajanju smeše"}]},"explanation":"Tačni parovi: Spajalica se pomera bez dodira — delovanje je moguće na daljinu; Gvožđe se izdvaja iz peska — magnet pomaže razdvajanju smeše; Aluminijum ostaje neprivučen — nisu svi metali privučeni; Udaljenija spajalica se ne pomera — rastojanje utiče na delovanje.","hint":"Zaključak treba da prati baš navedeno opažanje."},{"gen_signature":"pid-materijali-4:banka:bezbednost-postupci-parovi","text":"Poveži situaciju u ogledu sa bezbednim postupkom.","options":{"left":[{"id":"l0","text":"Nepoznata tečnost"},{"id":"l1","text":"Oštećen mrežni kabl"},{"id":"l2","text":"Sitni metalni opiljci"},{"id":"l3","text":"Zagrevanje u demonstraciji"}],"right":[{"id":"r3","text":"posmatramo sa dogovorenog odstojanja"},{"id":"r0","text":"ne probamo je"},{"id":"r1","text":"ne koristimo ga i obavestimo odraslog"},{"id":"r2","text":"ne stavljamo ih u usta i pratimo uputstva odraslog"}]},"explanation":"Tačni parovi: Nepoznata tečnost — ne probamo je; Oštećen mrežni kabl — ne koristimo ga i obavestimo odraslog; Sitni metalni opiljci — ne stavljamo ih u usta i pratimo uputstva odraslog; Zagrevanje u demonstraciji — posmatramo sa dogovorenog odstojanja.","hint":"Ogledi nisu poziv na samostalne rizične radnje."},{"gen_signature":"pid-materijali-4:banka:smese-opazanja-parovi","text":"Poveži opažanje u posudi sa procesom.","options":{"left":[{"id":"l0","text":"Čestice se spuštaju na dno"},{"id":"l1","text":"Bistra tečnost pažljivo se preliva iznad taloga"},{"id":"l2","text":"Nerastvorene čestice ostaju na filteru"},{"id":"l3","text":"Tečnost polako odlazi u vazduh"}],"right":[{"id":"r3","text":"isparavanje"},{"id":"r1","text":"odlivanje"},{"id":"r0","text":"taloženje"},{"id":"r2","text":"filtriranje"}]},"explanation":"Tačni parovi: Čestice se spuštaju na dno — taloženje; Bistra tečnost pažljivo se preliva iznad taloga — odlivanje; Nerastvorene čestice ostaju na filteru — filtriranje; Tečnost polako odlazi u vazduh — isparavanje.","hint":"Prati kretanje sastojaka."},{"gen_signature":"pid-proslost-srbije-4:banka:nemanjici-rastko","text":"Kako se Sveti Sava zvao pre nego što je postao monah?","options":[{"id":"o0","text":"Rastko Nemanjić"},{"id":"o1","text":"Vuk Karadžić"},{"id":"o2","text":"Dositej Obradović"},{"id":"o3","text":"Mihajlo Pupin"}],"explanation":"Sveti Sava je rođen kao Rastko, sin Stefana Nemanje.","hint":"Bio je najmlađi sin Stefana Nemanje."},{"gen_signature":"pid-proslost-srbije-4:banka:nemanjici-prosveta","text":"Zašto se Sveti Sava posebno pamti u školama Srbije?","options":[{"id":"o0","text":"zato što je izumeo telefon"},{"id":"o1","text":"zbog značaja za prosvetu i kulturu"},{"id":"o2","text":"zato što je vozio prvi automobil"},{"id":"o3","text":"zato što je osnovao internet"}],"explanation":"Sveti Sava je važna ličnost srpske prosvetne, kulturne i crkvene istorije.","hint":"Poveži školsku slavu sa učenjem i kulturom."},{"gen_signature":"pid-proslost-srbije-4:banka:licnosti-doprinosi-parovi","text":"Poveži ličnost srpske prošlosti sa njenim doprinosom.","options":{"left":[{"id":"l0","text":"Sveti Sava"},{"id":"l1","text":"Stefan Prvovenčani"},{"id":"l2","text":"Dositej Obradović"},{"id":"l3","text":"Vuk Karadžić"}],"right":[{"id":"r0","text":"prosveta i samostalnost srpske crkve"},{"id":"r3","text":"reforma jezika i pisma"},{"id":"r2","text":"prosvetiteljski rad i obrazovanje"},{"id":"r1","text":"prvi kralj iz dinastije Nemanjića"}]},"explanation":"Tačni parovi: Sveti Sava — prosveta i samostalnost srpske crkve; Stefan Prvovenčani — prvi kralj iz dinastije Nemanjića; Dositej Obradović — prosvetiteljski rad i obrazovanje; Vuk Karadžić — reforma jezika i pisma.","hint":"Svaki opis naglašava drugačiji doprinos."},{"gen_signature":"pid-proslost-srbije-4:banka:kultura-pojmovi-parovi","text":"Poveži pojam srednjovekovne kulture sa značenjem.","options":{"left":[{"id":"l0","text":"Rukopis"},{"id":"l1","text":"Zakonik"},{"id":"l2","text":"Zadužbina"},{"id":"l3","text":"Freska"}],"right":[{"id":"r1","text":"zbirka pravnih pravila"},{"id":"r3","text":"slika na vlažnom zidnom malteru"},{"id":"r2","text":"trajno dobro koje ostavlja osnivač"},{"id":"r0","text":"tekst napisan rukom"}]},"explanation":"Tačni parovi: Rukopis — tekst napisan rukom; Zakonik — zbirka pravnih pravila; Zadužbina — trajno dobro koje ostavlja osnivač; Freska — slika na vlažnom zidnom malteru.","hint":"Razlikuj tekst, pravila, građevinu i slikarstvo."},{"gen_signature":"pid-proslost-srbije-4:banka:svakodnevica-uloge-parovi","text":"Poveži osobu sa radom u starom naselju.","options":{"left":[{"id":"l0","text":"Zemljoradnik"},{"id":"l1","text":"Trgovac"},{"id":"l2","text":"Prepisivač"},{"id":"l3","text":"Grnčar"}],"right":[{"id":"r1","text":"kupovina i prodaja robe"},{"id":"r3","text":"izrada glinenog posuđa"},{"id":"r2","text":"ručno umnožavanje knjiga"},{"id":"r0","text":"obrađivanje njive"}]},"explanation":"Tačni parovi: Zemljoradnik — obrađivanje njive; Trgovac — kupovina i prodaja robe; Prepisivač — ručno umnožavanje knjiga; Grnčar — izrada glinenog posuđa.","hint":"Pođi od naziva zanimanja."},{"gen_signature":"pid-proslost-srbije-4:banka:poredjenje-epohe-parovi","text":"Poveži opis sa primerom života koji mu odgovara.","options":{"left":[{"id":"l0","text":"Srednjovekovna knjiga"},{"id":"l1","text":"Stara zanatska radionica"},{"id":"l2","text":"Razvoj železnice"},{"id":"l3","text":"Savremena digitalna komunikacija"}],"right":[{"id":"r2","text":"prevoz putnika i robe vozom"},{"id":"r3","text":"slanje elektronske poruke"},{"id":"r0","text":"rukom prepisan tekst na listovima"},{"id":"r1","text":"alatke i ručni rad majstora"}]},"explanation":"Tačni parovi: Srednjovekovna knjiga — rukom prepisan tekst na listovima; Stara zanatska radionica — alatke i ručni rad majstora; Razvoj železnice — prevoz putnika i robe vozom; Savremena digitalna komunikacija — slanje elektronske poruke.","hint":"Ne pripisuj novije uređaje starijim vremenima."},{"gen_signature":"pid-proslost-srbije-4:banka:izvori-teme-parovi","text":"Poveži istorijsko pitanje sa izvorom koji mu najviše odgovara.","options":{"left":[{"id":"l0","text":"Kako je izgledalo srednjovekovno pismo?"},{"id":"l1","text":"Koju je robu trgovac prodao?"},{"id":"l2","text":"Kako je izgledao stari grad?"},{"id":"l3","text":"Koji je alat koristio zanatlija?"}],"right":[{"id":"r0","text":"sačuvani rukopis"},{"id":"r1","text":"njegova sačuvana trgovačka knjiga"},{"id":"r3","text":"sačuvane alatke iz radionice"},{"id":"r2","text":"plan grada iz tog vremena"}]},"explanation":"Tačni parovi: Kako je izgledalo srednjovekovno pismo? — sačuvani rukopis; Koju je robu trgovac prodao? — njegova sačuvana trgovačka knjiga; Kako je izgledao stari grad? — plan grada iz tog vremena; Koji je alat koristio zanatlija? — sačuvane alatke iz radionice.","hint":"Izaberi izvor koji neposredno govori o traženom podatku."}]'::jsonb) as u(
    gen_signature text, text text, options jsonb, explanation text, hint text
  )
  where q.owner_id = v_owner
    and q.gen_signature = u.gen_signature
    and row(q.text, q.options, q.explanation, q.hint)
      is distinct from row(u.text, u.options, u.explanation, u.hint);
end $$;
